import React, { useState, useEffect } from "react";
import axios from "axios";
import { useNavigate } from "react-router-dom";

const API_BASE_URL = process.env.REACT_APP_API_BASE_URL || "http://localhost:8080";

export default function AdminDepositRequests() {
  const [requests, setRequests] = useState([]);
  const [loading, setLoading] = useState(true);
  const [message, setMessage] = useState("");
  const [updateMethod, setUpdateMethod] = useState("bkash");
  const [updateNumber, setUpdateNumber] = useState("");
  const [role, setRole] = useState("");

  const authToken = localStorage.getItem("authToken");
  const navigate = useNavigate();

  useEffect(() => {
    if (!authToken) return;

    const fetchProfileAndRequests = async () => {
      try {
        // Fetch user profile
        const profileRes = await axios.get(`${API_BASE_URL}/api/user/profile`, {
          headers: { Authorization: `Bearer ${authToken}` },
        });
        setRole(profileRes.data.role || "");

        // Fetch all deposit requests
        const depositRes = await axios.get(`${API_BASE_URL}/api/deposit/all-history`, {
          headers: { Authorization: `Bearer ${authToken}` },
        });

        const sortedData = depositRes.data.sort((a, b) => {
          const diff = new Date(b.requestedAt) - new Date(a.requestedAt);
          return diff !== 0 ? diff : b.id - a.id;
        });
        setRequests(sortedData);
      } catch (err) {
        setMessage("❌ Failed to load data");
      } finally {
        setLoading(false);
      }
    };

    fetchProfileAndRequests();
  }, [authToken]);

  const handleAction = async (id, action) => {
    try {
      await axios.post(`${API_BASE_URL}/api/deposit/${action}/${id}`, null, {
        headers: { Authorization: `Bearer ${authToken}` },
      });
      setMessage(`✅ ${action} successful`);
      setRequests((prev) => prev.filter((r) => r.id !== id));
    } catch (err) {
      setMessage(`❌ Failed to ${action}`);
    }
  };

  const handleUpdatePayment = async (gameId) => {
    if (!updateNumber.trim()) {
      setMessage("❌ Enter a valid number");
      return;
    }
    try {
      const res = await axios.post(
        `${API_BASE_URL}/api/payment-config/update-by-gameid`,
        null,
        {
          params: { gameId, method: updateMethod, number: updateNumber },
          headers: { Authorization: `Bearer ${authToken}` },
        }
      );
      setMessage(`✅ Updated ${res.data.method}: ${res.data.number}`);
    } catch (err) {
      setMessage("❌ Failed to update payment config");
    }
  };

  const formatDate = (dateString) => {
    if (!dateString) return "N/A";
    const date = new Date(dateString);
    return date.toLocaleString();
  };

  const renderStatusBadge = (status) => {
    switch (status) {
      case "APPROVED":
        return <span className="px-2 py-1 rounded bg-green-500 text-white">Completed</span>;
      case "REJECTED":
        return <span className="px-2 py-1 rounded bg-red-500 text-white">Rejected</span>;
      case "PENDING":
        return <span className="px-2 py-1 rounded bg-yellow-400 text-black">Pending</span>;
      default:
        return <span className="px-2 py-1 rounded bg-gray-400 text-white">{status}</span>;
    }
  };

  if (loading) return <div className="text-center p-6">⏳ Loading...</div>;

  return (
    <div className="p-6 max-w-6xl mx-auto">
      <button
        onClick={() => navigate("/")}
        className="mb-6 px-4 py-2 bg-indigo-500 hover:bg-indigo-600 text-white rounded"
      >
        ← Back
      </button>

      {message && (
        <div
          className={`mb-4 p-3 rounded font-semibold text-center ${
            message.startsWith("✅") ? "bg-green-100 text-green-700" : "bg-red-100 text-red-700"
          }`}
        >
          {message}
        </div>
      )}

      <h2 className="text-2xl font-bold text-center mb-6">🧾 All Deposit Requests</h2>

      <div className="mb-6 flex space-x-3 items-center">
        <select
          value={updateMethod}
          onChange={(e) => setUpdateMethod(e.target.value)}
          className="border px-2 py-1 rounded"
        >
          <option value="bkash">bKash</option>
          <option value="nagad">Nagad</option>
          <option value="rocket">Rocket</option>
        </select>
        <input
          type="text"
          placeholder="Enter number"
          value={updateNumber}
          onChange={(e) => setUpdateNumber(e.target.value)}
          className="border px-2 py-1 rounded"
        />
      </div>

      <div className="overflow-x-auto border rounded shadow">
        <table className="min-w-full text-sm">
          <thead className="bg-gray-100 border-b">
            <tr>
              <th className="py-2 px-3 text-center">ID</th>
              <th className="py-2 px-3 text-center">Game ID</th>
              <th className="py-2 px-3 text-center">Mobile</th>
              <th className="py-2 px-3 text-center">Amount</th>
              <th className="py-2 px-3 text-center">Method</th>
              <th className="py-2 px-3 text-center">Txn ID</th>
              <th className="py-2 px-3 text-center">Sender</th>
              <th className="py-2 px-3 text-center">Status</th>
              <th className="py-2 px-3 text-center">Requested At</th>
              <th className="py-2 px-3 text-center">Actions</th>
            </tr>
          </thead>
          <tbody>
            {requests.map((r) => (
              <tr key={r.id} className="border-b hover:bg-gray-50 transition">
                <td className="py-2 px-3 text-center">{r.id}</td>
                <td className="py-2 px-3 text-center">{r.gameId}</td>
                <td className="py-2 px-3 text-center">{r.mobile}</td>
                <td className="py-2 px-3 text-center font-semibold text-green-600">
                  ৳ {Number(r.amount).toFixed(2)}
                </td>
                <td className="py-2 px-3 text-center">{r.method}</td>
                <td className="py-2 px-3 text-center">{r.transactionId}</td>
                <td className="py-2 px-3 text-center">{r.senderNumber}</td>
                <td className="py-2 px-3 text-center">{renderStatusBadge(r.status)}</td>
                <td className="py-2 px-3 text-center">{formatDate(r.requestedAt)}</td>
                <td className="py-2 px-3 text-center space-x-2">
                  {r.status === "PENDING" && (
                    <>
                      <button
                        onClick={() => handleAction(r.id, "approve")}
                        className="px-3 py-1 bg-green-500 hover:bg-green-600 text-white rounded"
                      >
                        Approve
                      </button>
                      <button
                        onClick={() => handleAction(r.id, "reject")}
                        className="px-3 py-1 bg-red-500 hover:bg-red-600 text-white rounded"
                      >
                        Reject
                      </button>
                    </>
                  )}
                  <button
                    onClick={() => handleUpdatePayment(r.gameId)}
                    className="px-3 py-1 bg-blue-500 hover:bg-blue-600 text-white rounded"
                  >
                    Update Payment
                  </button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}
